/** D144: fixed product-colour screen and bare white symbol; fade to the app, with no minimum dwell. */
@Composable
fun SbStart(
    ready: Boolean,
    product: SebaroProduct,
    tile: @Composable (Modifier) -> Unit,
    content: @Composable () -> Unit,
) {
    val t = SebaroTheme.tokens
    val state = remember { SbStartState() }
    val progress = remember { Animatable(0f) }
    LaunchedEffect(ready) {
        if (ready && state.running) {
            withContext(SbFullMotionScale) {
                progress.animateTo(1f, tween(t.x.enterFadeDuration, easing = t.motion.easingStandard))
            }
            state.running = false
        }
    }
    CompositionLocalProvider(LocalSbStartState provides state) {
        Box(Modifier.fillMaxSize()) {
            content()
            if (state.running) {
                Box(Modifier.fillMaxSize().graphicsLayer { alpha = 1f - progress.value }
                    .background(product.tile.tile), contentAlignment = Alignment.Center) {
                    CompositionLocalProvider(LocalContentColor provides product.tile.glyph) {
                        tile(Modifier.size(t.x.startTileSize))
                    }
                }
            }
        }
    }
